const b = $input.first().json.body ?? $input.first().json;
if (!b.trip_id || !b.route_id) throw new Error('Missing trip_id or route_id');
const token = 'TOK-' + Date.now() + '-' + Math.random().toString(36).slice(2,8).toUpperCase();
// Store trip state in n8n workflow static data (in-memory for demo)
// For production: use a database or Redis via n8n credentials
const state = this.getWorkflowStaticData('node');
state[b.trip_id] = {
  trip_id: b.trip_id,
  route_id: b.route_id,
  session_token: token,
  trusted_contacts: b.trusted_contacts ?? [],
  state: 'ACTIVE',
  started_at: new Date().toISOString(),
  last_lat: null, last_lng: null
};
return [{json: {trip_id: b.trip_id, session_token: token, status: 'ACTIVE'}}];

// ─── Location update handler ──────────────────────────────────────────────
// Receives GPS from the Android app, checks proximity to high-risk segments,
// returns a risk_event if check-in is required.
//
// In a full implementation: compare the received lat/lng against the
// precomputed route corridor risk segments from the plan-trip workflow.
// For the hackathon: use a simple distance-from-destination heuristic
// combined with the trip's known risk_level.

const b = $input.first().json.body ?? $input.first().json;
const state = this.getWorkflowStaticData('node');
const trip = state[b.trip_id];

if (!trip) {
  return [{json: {error: 'Trip not found', trip_id: b.trip_id, risk_event: null}}];
}

// Validate session token
if (trip.session_token !== b.session_token) {
  return [{json: {error: 'Invalid session token', trip_id: b.trip_id, risk_event: null}}];
}

// Update last known location
trip.last_lat = b.latitude;
trip.last_lng = b.longitude;
trip.last_update = new Date().toISOString();
state[b.trip_id] = trip;

// ── Risk zone check (simplified for hackathon) ────────────────────────────
// In production: compare against precomputed high-risk polyline segments.
// For demo: trigger CHECK_IN_REQUIRED if trip state transitions to a 
// known risk zone (determined by a synthetic check based on trip progress).

let riskEvent = null;
const nowMs = Date.now();

// Only trigger check-in if trip state is ACTIVE (not already pending)
// and we haven't sent one in the last 5 minutes
if (trip.state === 'ACTIVE') {
  const lastCheckIn = trip.last_checkin_ms ?? 0;
  const minsBetween = (nowMs - lastCheckIn) / (1000 * 60);

  // Demo mode: trigger after the first location update if demo_trigger is set
  // Real mode: this would check against route segment risk scores
  if (b.demo_trigger === true && minsBetween > 1) {
    riskEvent = {
      type: 'CHECK_IN_REQUIRED',
      risk_level: 'HIGH',
      message: 'You have entered a reported-risk area. Are you safe?',
      check_in_deadline_ms: nowMs + (5 * 60 * 1000) // 5 minute window
    };
    trip.state = 'CHECK_IN_PENDING';
    trip.checkin_deadline_ms = riskEvent.check_in_deadline_ms;
    trip.last_checkin_ms = nowMs;
    state[b.trip_id] = trip;
  }
}

return [{json: {trip_id: b.trip_id, risk_event: riskEvent}}];

const b = $input.first().json.body ?? $input.first().json;
const state = this.getWorkflowStaticData('node');
const trip = state[b.trip_id];

if (!trip) return [{json: {error: 'Trip not found', new_state: 'UNKNOWN', message: 'Trip not found'}}];
if (trip.session_token !== b.session_token) return [{json: {error: 'Unauthorized', new_state: 'UNKNOWN', message: 'Invalid token'}}];

let newState, message;
if (b.status === 'SAFE') {
  newState = 'ACTIVE';
  message = 'Check-in confirmed. Trip monitoring continues.';
  trip.state = 'ACTIVE';
  trip.checkin_deadline_ms = null;
} else if (b.status === 'SOS') {
  newState = 'SOS_ACTIVE';
  message = 'SOS received. Escalation initiated.';
  trip.state = 'SOS_ACTIVE';
} else {
  newState = trip.state;
  message = 'Unknown status';
}
state[b.trip_id] = trip;
return [{json: {trip_id: b.trip_id, new_state: newState, message}}];

const b = $input.first().json.body ?? $input.first().json;
const state = this.getWorkflowStaticData('node');
const trip = state[b.trip_id];
if (trip && trip.session_token === b.session_token) {
  trip.state = 'COMPLETED';
  trip.ended_at = new Date().toISOString();
  state[b.trip_id] = trip;
}
return [{json: {trip_id: b.trip_id, status: 'COMPLETED'}}];
